// NetworkHostGroupBy is the group-by builder for NetworkHost entities.
type NetworkHostGroupBy struct {
	selector
	build *NetworkHostQuery
}

// Aggregate adds the given aggregation functions to the group-by query.
func (nhgb *NetworkHostGroupBy) Aggregate(fns ...AggregateFunc) *NetworkHostGroupBy {
	nhgb.fns = append(nhgb.fns, fns...)
	return nhgb
}

// Scan applies the selector query and scans the result into the given value.
func (nhgb *NetworkHostGroupBy) Scan(ctx context.Context, v any) error {
	ctx = setContextOp(ctx, nhgb.build.ctx, ent.OpQueryGroupBy)
	if err := nhgb.build.prepareQuery(ctx); err != nil {
		return err
	}
	return scanWithInterceptors[*NetworkHostQuery, *NetworkHostGroupBy](ctx, nhgb.build, nhgb, nhgb.build.inters, v)
}

func (nhgb *NetworkHostGroupBy) sqlScan(ctx context.Context, root *NetworkHostQuery, v any) error {
	selector := root.sqlQuery(ctx).Select()
	aggregation := make([]string, 0, len(nhgb.fns))
	for _, fn := range nhgb.fns {
		aggregation = append(aggregation, fn(selector))
	}
	if len(selector.SelectedColumns()) == 0 {
		columns := make([]string, 0, len(*nhgb.flds)+len(nhgb.fns))
		for _, f := range *nhgb.flds {
			columns = append(columns, selector.C(f))
		}
		columns = append(columns, aggregation...)
		selector.Select(columns...)
	}
	selector.GroupBy(selector.Columns(*nhgb.flds...)...)
	if err := selector.Err(); err != nil {
		return err
	}
	rows := &sql.Rows{}
	query, args := selector.Query()
	if err := nhgb.build.driver.Query(ctx, query, args, rows); err != nil {
		return err
	}
	defer rows.Close()
	return sql.ScanSlice(rows, v)
}

