// Scan applies the selector query and scans the result into the given value.
func (nhs *NetworkHostSelect) Scan(ctx context.Context, v any) error {
	ctx = setContextOp(ctx, nhs.ctx, ent.OpQuerySelect)
	if err := nhs.prepareQuery(ctx); err != nil {
		return err
	}
	return scanWithInterceptors[*NetworkHostQuery, *NetworkHostSelect](ctx, nhs.NetworkHostQuery, nhs, nhs.inters, v)
}

func (nhs *NetworkHostSelect) sqlScan(ctx context.Context, root *NetworkHostQuery, v any) error {
	selector := root.sqlQuery(ctx)
	aggregation := make([]string, 0, len(nhs.fns))
	for _, fn := range nhs.fns {
		aggregation = append(aggregation, fn(selector))
	}
	switch n := len(*nhs.selector.flds); {
	case n == 0 && len(aggregation) > 0:
		selector.Select(aggregation...)
	case n != 0 && len(aggregation) > 0:
		selector.AppendSelect(aggregation...)
	}
	rows := &sql.Rows{}
	query, args := selector.Query()
	if err := nhs.driver.Query(ctx, query, args, rows); err != nil {
		return err
	}
	defer rows.Close()
	return sql.ScanSlice(rows, v)
}
